def transform(grid):
    """Fill every single-cell horizontal gap between identical non-background marks with color 2."""
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marks = {v for v in counts if v != background}
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == background and row[c - 1] in marks and row[c - 1] == row[c + 1]:
                out[r][c] = 2
    return out
